export const DEFAULT_BATCH_SIZE = 16;
type Options = { batchSize?: number };
export function settings(env: Record<string, string | undefined>, profile: Options, patch: Options) {
  const fromEnv = { batchSize: Number(env.PICK_BATCH_SIZE ?? DEFAULT_BATCH_SIZE) };
  const merged = { ...fromEnv, ...profile, ...patch };
  return { batchSize: merged.batchSize ?? DEFAULT_BATCH_SIZE };
}
